.card-title {
  font-size: clamp(1.25rem, 4cqi, 1.75rem);
  line-height: 1.2;
}

.card-description {
  font-size: clamp(0.875rem, 3cqi, 1rem);
  line-height: 1.5;
  color: #666;
}

/* Container query: horizontal layout when space allows */
@container (min-width: 500px) {
  .card {
    flex-direction: row;
    gap: 1.5rem;
  }

  .card-image {
    width: 200px;
    flex-shrink: 0;
  }

  .card-content {
    flex: 1;
  }
