/* Viewport query: increase padding on larger screens */
@media (min-width: 1024px) {
  .card {
    padding: 1.5rem;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .card {
    transition: none;
  }
}
